D1.before:
BEGIN;
CREATE TEMP TABLE cap_D1 AS SELECT a.alertid,a.resultid,a.status,a.acknowledgedat FROM labalert a JOIN testresult r USING(resultid) JOIN labtest l USING(labtestid) WHERE a.status IN ('Acknowledged','Resolved') AND a.acknowledgedat<TIMESTAMP '2026-07-01' AND l.status='Completed' ORDER BY a.alertid LIMIT 5;
SELECT 'D1 before' AS phase,* FROM cap_D1;

D2.before:
BEGIN;
CREATE TEMP TABLE cap_D2 AS SELECT l.labtestid,l.orderid,l.status,l.scheduledat FROM labtest l JOIN testorder o USING(orderid) WHERE l.status='Scheduled' AND o.orderedat<TIMESTAMP '2026-04-01' AND NOT EXISTS(SELECT 1 FROM testresult r WHERE r.labtestid=l.labtestid) AND EXISTS(SELECT 1 FROM labtest other WHERE other.orderid=l.orderid AND other.labtestid<>l.labtestid AND other.status<>'Scheduled') ORDER BY l.labtestid LIMIT 5;
SELECT 'D2 before' AS phase,* FROM cap_D2;

D3.before:
BEGIN;
CREATE TEMP TABLE cap_D3 AS SELECT d.doctorid,d.firstname,d.lastname,d.specialty FROM doctor d WHERE d.licensenumber LIKE 'DEMO-LIC-%' AND NOT EXISTS(SELECT 1 FROM testorder o WHERE o.doctorid=d.doctorid) AND EXISTS(SELECT 1 FROM doctor active JOIN testorder o USING(doctorid) WHERE active.specialty=d.specialty AND active.doctorid<>d.doctorid) ORDER BY d.doctorid LIMIT 5;
SELECT 'D3 before' AS phase,* FROM cap_D3;

U1.before:
BEGIN;
CREATE TEMP TABLE cap_U1 AS SELECT o.orderid,o.patientid,o.doctorid,o.priority FROM testorder o WHERE o.priority<>'STAT' AND EXISTS(SELECT 1 FROM labtest l JOIN testresult r USING(labtestid) JOIN labalert a USING(resultid) WHERE l.orderid=o.orderid AND r.isabnormal AND a.status='Open' AND a.severity IN ('High','Critical')) ORDER BY o.orderid LIMIT 5;
SELECT 'U1 before' AS phase,* FROM cap_U1;

U1.after:
UPDATE testorder o SET priority='STAT'
WHERE o.priority<>'STAT' AND EXISTS (
 SELECT 1 FROM labtest l JOIN testresult r USING(labtestid)
 JOIN labalert a USING(resultid)
 WHERE l.orderid=o.orderid AND r.isabnormal AND a.status='Open'
   AND a.severity IN ('High','Critical')
)
RETURNING o.orderid,o.patientid,o.doctorid,o.priority;
SELECT 'U1 after' AS phase,b.orderid,t.orderid,t.patientid,t.doctorid,t.priority,t.orderid IS NULL AS deleted
FROM cap_U1 b LEFT JOIN testorder t USING(orderid) ORDER BY b.orderid;

U2.before:
BEGIN;
CREATE TEMP TABLE cap_U2 AS SELECT a.alertid,a.resultid,a.status,a.acknowledgedat FROM labalert a JOIN testresult r USING(resultid) JOIN labtest l USING(labtestid) JOIN testorder o USING(orderid) WHERE a.status='Acknowledged' AND a.acknowledgedat<TIMESTAMP '2026-07-01' AND l.status='Completed' AND o.orderedat<r.resultedat ORDER BY a.alertid LIMIT 5;
SELECT 'U2 before' AS phase,* FROM cap_U2;

U3.before:
BEGIN;
CREATE TEMP TABLE cap_U3 AS SELECT l.labtestid,l.orderid,l.status,l.technicianid FROM labtest l JOIN testorder o USING(orderid) WHERE l.status='Scheduled' AND l.technicianid IS NULL AND o.priority IN ('Urgent','STAT') ORDER BY l.labtestid LIMIT 5;
SELECT 'U3 before' AS phase,* FROM cap_U3;
